-- ============================================================
-- Migration: 005_admin_rls.sql
-- ============================================================
-- ============================================================
-- PunterStat — Stage 9: Admin RLS bypass policies
-- ============================================================

-- Helper: returns true if the current authenticated user is an admin
create or replace function public.is_admin()
returns boolean language sql stable security definer as $$
  select exists (
    select 1 from public.profiles
    where user_id = auth.uid() and role = 'admin'
  );
$$;

-- ============================================================
-- PROFILES — admins can read and update all profiles
-- ============================================================
create policy "Admins read all profiles"
  on public.profiles for select
  using (public.is_admin());

create policy "Admins update all profiles"
  on public.profiles for update
  using (public.is_admin());

-- ============================================================
-- SUBSCRIPTIONS — admins can read and update all subscriptions
-- ============================================================
create policy "Admins read all subscriptions"
  on public.subscriptions for select
  using (public.is_admin());

create policy "Admins update all subscriptions"
  on public.subscriptions for update
  using (public.is_admin());

-- ============================================================
-- COURSES — admins can do full CRUD
-- ============================================================
create policy "Admins full access to courses"
  on public.courses for all
  using (public.is_admin())
  with check (public.is_admin());

-- ============================================================
-- LESSONS — admins can do full CRUD
-- ============================================================
create policy "Admins full access to lessons"
  on public.lessons for all
  using (public.is_admin())
  with check (public.is_admin());

-- ============================================================
-- COURSE CATEGORIES — admins can do full CRUD
-- ============================================================
create policy "Admins full access to course categories"
  on public.course_categories for all
  using (public.is_admin())
  with check (public.is_admin());

-- ============================================================
-- BLOG POSTS — admins can do full CRUD
-- ============================================================
create policy "Admins full access to blog posts"
  on public.blog_posts for all
  using (public.is_admin())
  with check (public.is_admin());

-- ============================================================
-- NOTIFICATIONS — admins can read all notifications
-- ============================================================
create policy "Admins read all notifications"
  on public.notifications for select
  using (public.is_admin());

-- ============================================================
-- FEATURE FLAGS — enable RLS + admin full access
-- ============================================================
alter table public.feature_flags enable row level security;

create policy "Admins full access to feature flags"
  on public.feature_flags for all
  using (public.is_admin())
  with check (public.is_admin());

-- ============================================================
-- AUDIT LOGS — enable RLS + admin read access
-- ============================================================
alter table public.audit_logs enable row level security;

create policy "Admins read all audit logs"
  on public.audit_logs for select
  using (public.is_admin());

create policy "Service insert audit logs"
  on public.audit_logs for insert
  with check (true);

-- ============================================================
-- ADMIN ROLES — admins can read the admin_roles table
-- ============================================================
alter table public.admin_roles enable row level security;

create policy "Admins read admin roles"
  on public.admin_roles for select
  using (public.is_admin());


-- ============================================================
-- Migration: 006_fixes.sql
-- ============================================================
-- ============================================================
-- PunterStat — Migration 006: Bug Fix Additions
-- Run in order after 005_admin_rls.sql
-- ============================================================

-- ── 1. welcome_sent guard on profiles ─────────────────────────────────────────
-- Prevents duplicate welcome emails when a user clicks the confirmation
-- link more than once. The auth callback checks this flag before sending
-- and marks it true immediately after queueing the email.
ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS welcome_sent boolean NOT NULL DEFAULT false;

-- ── 2. Denormalised author_name on blog_posts ──────────────────────────────────
-- auth.users is not queryable by the anon key (Supabase security model).
-- Rather than changing RLS or adding a public profiles join, we store the
-- author's display name at write time so the public blog never needs to
-- look up auth.users.
ALTER TABLE public.blog_posts
  ADD COLUMN IF NOT EXISTS author_name text;

-- Backfill existing posts from the profiles table (best-effort — posts
-- whose author has been deleted will remain NULL, which is handled in UI).
UPDATE public.blog_posts bp
SET    author_name = p.display_name
FROM   public.profiles p
WHERE  bp.author_id = p.user_id
  AND  bp.author_name IS NULL;


-- ============================================================
-- Migration: 007_blog_fts.sql
-- ============================================================
-- ============================================================
-- PunterStat — Migration 007: Blog Full-Text Search
-- Run after 006_fixes.sql
-- ============================================================

-- Add a stored generated tsvector column that indexes title,
-- excerpt, and content together so textSearch() works across
-- all three fields in a single query.
ALTER TABLE public.blog_posts
  ADD COLUMN IF NOT EXISTS fts tsvector
  GENERATED ALWAYS AS (
    to_tsvector(
      'english',
      coalesce(title, '')   || ' ' ||
      coalesce(excerpt, '') || ' ' ||
      coalesce(content, '')
    )
  ) STORED;

-- GIN index keeps full-text lookups fast even as the post count grows.
CREATE INDEX IF NOT EXISTS blog_posts_fts_idx
  ON public.blog_posts USING gin(fts);


