-- Migration: 008_odds_cache.sql
-- ============================================================
-- ============================================================
-- PunterStat — Migration 008: Odds Cache + API Quota Log
-- Run in order after 007_blog_fts.sql
-- Part of the Quant Layer rollout (see PLAN_QUANT_LAYER.md, Stage 13)
-- ============================================================

-- ── 1. odds_cache ────────────────────────────────────────────────────────
-- Persistent floor for The Odds API responses (500 credits/month budget).
-- Every fetch is cached here so repeated reads (Bet Simulator, Spot The
-- Value) never re-spend a credit; only a scheduled refresh or explicit
-- cache-miss triggers a new API call.
CREATE TABLE IF NOT EXISTS public.odds_cache (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sport_key text NOT NULL,
  event_id text NOT NULL,
  home_team text NOT NULL,
  away_team text NOT NULL,
  commence_time timestamptz NOT NULL,
  bookmaker text NOT NULL,
  market_key text NOT NULL,
  outcomes jsonb NOT NULL,
  fetched_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS odds_cache_event_id_idx ON public.odds_cache (event_id);
CREATE INDEX IF NOT EXISTS odds_cache_expires_at_idx ON public.odds_cache (expires_at);
CREATE UNIQUE INDEX IF NOT EXISTS odds_cache_event_bookmaker_market_idx
  ON public.odds_cache (event_id, bookmaker, market_key);

ALTER TABLE public.odds_cache ENABLE ROW LEVEL SECURITY;

-- Cache is derived, non-sensitive market data — safe to read for any
-- authenticated user; writes are service-role only (server-side fetch).
CREATE POLICY "odds_cache_select_authenticated" ON public.odds_cache
  FOR SELECT TO authenticated USING (true);

-- ── 2. api_quota_log ─────────────────────────────────────────────────────
-- Tracks daily/monthly usage per external API so lib/sports-data/router.ts
-- can route between primary/secondary sources with hysteresis and avoid
-- exceeding free-tier quotas (API-Football: 100 req/day, Odds API: 500
-- credits/month, football-data.org: 10 req/min).
CREATE TABLE IF NOT EXISTS public.api_quota_log (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  provider text NOT NULL,
  request_count integer NOT NULL DEFAULT 1,
  window_start timestamptz NOT NULL,
  window_end timestamptz NOT NULL,
  last_request_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS api_quota_log_provider_window_idx
  ON public.api_quota_log (provider, window_start, window_end);

ALTER TABLE public.api_quota_log ENABLE ROW LEVEL SECURITY;

-- Internal accounting table — no client access; service role only
-- (no policy grants SELECT/INSERT/UPDATE to anon/authenticated).


-- ============================================================
-- Migration: 009_fixtures_cache.sql
-- ============================================================
-- ============================================================
-- PunterStat — Migration 009: Fixtures Cache + Prediction Records
-- Run in order after 008_odds_cache.sql
-- Part of the Quant Layer rollout (see PLAN_QUANT_LAYER.md, Stage 13)
-- ============================================================

-- ── 1. fixtures_cache ────────────────────────────────────────────────────
-- Shared cache for match/fixture data from both API-Football (primary,
-- 100 req/day) and football-data.org (secondary, top-5 leagues fallback).
-- `source` records which provider populated a given row so the UI and
-- router can reason about data freshness/quality per fixture.
CREATE TABLE IF NOT EXISTS public.fixtures_cache (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source text NOT NULL CHECK (source IN ('api-football', 'football-data')),
  external_id text NOT NULL,
  league text NOT NULL,
  season text,
  home_team text NOT NULL,
  away_team text NOT NULL,
  kickoff timestamptz NOT NULL,
  status text NOT NULL DEFAULT 'scheduled',
  home_score integer,
  away_score integer,
  raw_payload jsonb NOT NULL,
  fetched_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS fixtures_cache_source_external_id_idx
  ON public.fixtures_cache (source, external_id);
CREATE INDEX IF NOT EXISTS fixtures_cache_kickoff_idx ON public.fixtures_cache (kickoff);
CREATE INDEX IF NOT EXISTS fixtures_cache_league_idx ON public.fixtures_cache (league);

ALTER TABLE public.fixtures_cache ENABLE ROW LEVEL SECURITY;

CREATE POLICY "fixtures_cache_select_authenticated" ON public.fixtures_cache
  FOR SELECT TO authenticated USING (true);

-- ── 2. prediction_records ───────────────────────────────────────────────
-- Created by the "Track This Prediction" button on the Match Breakdown
-- Analyzer (Stage 16). Stores the model's output at prediction time; once
-- the real match result is known, the Calibration Engine (Stage 19) scores
-- these rows for a Brier score / accuracy / calibration curve.
CREATE TABLE IF NOT EXISTS public.prediction_records (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  fixture_id uuid REFERENCES public.fixtures_cache(id) ON DELETE SET NULL,
  home_team text NOT NULL,
  away_team text NOT NULL,
  match_date timestamptz,
  predicted_home_win_prob numeric(5, 4) NOT NULL,
  predicted_draw_prob numeric(5, 4) NOT NULL,
  predicted_away_win_prob numeric(5, 4) NOT NULL,
  model_input jsonb NOT NULL,
  actual_result text CHECK (actual_result IN ('home_win', 'draw', 'away_win')),
  resolved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS prediction_records_user_id_idx ON public.prediction_records (user_id);
CREATE INDEX IF NOT EXISTS prediction_records_fixture_id_idx ON public.prediction_records (fixture_id);
CREATE INDEX IF NOT EXISTS prediction_records_resolved_idx ON public.prediction_records (resolved_at);

ALTER TABLE public.prediction_records ENABLE ROW LEVEL SECURITY;

-- Private per-user data — same pattern as other user-owned tables
-- (e.g. bookmarks, simulation_history).
CREATE POLICY "prediction_records_select_own" ON public.prediction_records
  FOR SELECT TO authenticated USING (auth.uid() = user_id);

CREATE POLICY "prediction_records_insert_own" ON public.prediction_records
  FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);

CREATE POLICY "prediction_records_update_own" ON public.prediction_records
  FOR UPDATE TO authenticated USING (auth.uid() = user_id);

CREATE POLICY "prediction_records_delete_own" ON public.prediction_records
  FOR DELETE TO authenticated USING (auth.uid() = user_id);


-- ============================================================
-- Migration: 010_access_control_audit_indexes.sql
-- ============================================================
-- ============================================================
-- PunterStat — Migration 010: Access Control, Audit Log RLS,
--              Data Isolation gaps, Performance Indexes
-- Target scale: 100 K registered users, 10 K concurrent
--
-- SAFE TO RE-RUN: every policy creation is wrapped in a DO
-- block that checks pg_policies before acting.
-- ============================================================

-- ── 1. AUDIT LOGS — complete the RLS setup started in migration 005 ──────
--
-- Migration 005 already did:
--   • ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY
--   • "Admins read all audit logs"  (admin SELECT)
--   • "Service insert audit logs" WITH CHECK (true)   ← too permissive
--
-- Migration 010 adds:
--   • User self-read policy (GDPR / transparency)
--   • Admin delete policy (retention management)
--   • Replaces the permissive "Service insert" policy with a
--     service-role-only INSERT so clients cannot forge audit records.
--     (No INSERT policy visible to authenticated role → only the service
--     role, which bypasses RLS entirely, may write.)

-- 1a. User self-read (idempotent guard)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'audit_logs'
      AND policyname = 'Users read own audit logs'
  ) THEN
    EXECUTE $p$
      CREATE POLICY "Users read own audit logs"
        ON public.audit_logs FOR SELECT TO authenticated
        USING (auth.uid() = user_id)
    $p$;
  END IF;
END $$;

-- 1b. Admin delete (retention management, idempotent)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'audit_logs'
      AND policyname = 'Admins delete audit logs'
  ) THEN
    EXECUTE $p$
      CREATE POLICY "Admins delete audit logs"
        ON public.audit_logs FOR DELETE
        USING (public.is_admin())
    $p$;
  END IF;
END $$;

-- 1c. Drop the over-permissive insert policy from migration 005 and do not
-- replace it with an authenticated-role INSERT policy.  The server-side
-- audit logger (lib/audit/logger.ts) uses createAdminClient() which runs
-- as the service role and therefore bypasses RLS entirely — it needs no
-- explicit policy.  Removing the old policy closes the forgery vector.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'audit_logs'
      AND policyname = 'Service insert audit logs'
  ) THEN
    EXECUTE $p$ DROP POLICY "Service insert audit logs" ON public.audit_logs $p$;
  END IF;
END $$;

-- ── 2. PREDICTION RECORDS — admin visibility (idempotent) ───────────────
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'prediction_records'
      AND policyname = 'Admins read all prediction records'
  ) THEN
    EXECUTE $p$
      CREATE POLICY "Admins read all prediction records"
        ON public.prediction_records FOR SELECT
        USING (public.is_admin())
    $p$;
  END IF;
END $$;

-- ── 3. FIXTURES CACHE — admin write access (idempotent) ─────────────────
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'fixtures_cache'
      AND policyname = 'Admins manage fixtures cache'
  ) THEN
    EXECUTE $p$
      CREATE POLICY "Admins manage fixtures cache"
        ON public.fixtures_cache FOR ALL
        USING (public.is_admin())
        WITH CHECK (public.is_admin())
    $p$;
  END IF;
END $$;

-- ── 4. ODDS CACHE — admin write access (idempotent) ─────────────────────
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'odds_cache'
      AND policyname = 'Admins manage odds cache'
  ) THEN
    EXECUTE $p$
      CREATE POLICY "Admins manage odds cache"
        ON public.odds_cache FOR ALL
        USING (public.is_admin())
        WITH CHECK (public.is_admin())
    $p$;
  END IF;
END $$;

-- ── 5. API QUOTA LOG — admin read access (idempotent) ───────────────────
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'api_quota_log'
      AND policyname = 'Admins read api quota log'
  ) THEN
    EXECUTE $p$
      CREATE POLICY "Admins read api quota log"
        ON public.api_quota_log FOR SELECT
        USING (public.is_admin())
    $p$;
  END IF;
END $$;

-- ── 6. MATCH ANALYSES — admin read access (idempotent) ──────────────────
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'match_analyses'
      AND policyname = 'Admins read all match analyses'
  ) THEN
    EXECUTE $p$
      CREATE POLICY "Admins read all match analyses"
        ON public.match_analyses FOR SELECT
        USING (public.is_admin())
    $p$;
  END IF;
END $$;

-- ── 7. PERFORMANCE INDEXES for 100 K users / 10 K concurrent ────────────
--
-- Design notes:
--   • lesson_progress and bookmarks are the hottest tables — every
--     dashboard load hits them per user.
--   • subscriptions partial index on active rows only (status = 'active'),
--     covering (user_id, current_period_end) for tier expiry checks.
--   • notifications partial index on unread rows eliminates full scans.
--   • audit_logs composite indexes: (user_id, created_at DESC) for paged
--     user-facing queries; (action, created_at DESC) for admin filtering.
--   • prediction_records partial index on resolved rows for calibration.
--   • All indexes use IF NOT EXISTS — safe to re-run.

-- lesson_progress
CREATE INDEX IF NOT EXISTS lesson_progress_user_lesson_idx
  ON public.lesson_progress (user_id, lesson_id);

CREATE INDEX IF NOT EXISTS lesson_progress_user_completed_idx
  ON public.lesson_progress (user_id, completed);

-- bookmarks
CREATE INDEX IF NOT EXISTS bookmarks_user_lesson_idx
  ON public.bookmarks (user_id, lesson_id);

-- subscriptions — access control tier check (partial: active rows only)
-- Column is current_period_end (not expires_at).
CREATE INDEX IF NOT EXISTS subscriptions_user_status_period_idx
  ON public.subscriptions (user_id, status, current_period_end)
  WHERE status = 'active';

CREATE INDEX IF NOT EXISTS subscriptions_plan_status_idx
  ON public.subscriptions (plan, status);

-- notifications — unread count per user
-- Column is is_read (not read).
CREATE INDEX IF NOT EXISTS notifications_user_unread_idx
  ON public.notifications (user_id, created_at DESC)
  WHERE is_read = false;

-- simulation_history
CREATE INDEX IF NOT EXISTS simulation_history_session_created_idx
  ON public.simulation_history (session_id, created_at DESC);

-- simulation_sessions
CREATE INDEX IF NOT EXISTS simulation_sessions_user_created_idx
  ON public.simulation_sessions (user_id, created_at DESC);

-- match_analysis uses author_id (not user_id) — see migration 001
CREATE INDEX IF NOT EXISTS match_analysis_author_created_idx
  ON public.match_analysis (author_id, created_at DESC);

-- audit_logs
CREATE INDEX IF NOT EXISTS audit_logs_user_created_idx
  ON public.audit_logs (user_id, created_at DESC);

CREATE INDEX IF NOT EXISTS audit_logs_action_created_idx
  ON public.audit_logs (action, created_at DESC);

-- prediction_records — calibration query
CREATE INDEX IF NOT EXISTS prediction_records_user_resolved_idx
  ON public.prediction_records (user_id, resolved_at DESC)
  WHERE resolved_at IS NOT NULL;

-- blog_posts — published listing
CREATE INDEX IF NOT EXISTS blog_posts_published_at_idx
  ON public.blog_posts (published_at DESC)
  WHERE is_published = true;

-- courses — published listing per category
CREATE INDEX IF NOT EXISTS courses_category_published_order_idx
  ON public.courses (category_id, sort_order)
  WHERE is_published = true;

-- lessons — published listing per course
CREATE INDEX IF NOT EXISTS lessons_course_published_order_idx
  ON public.lessons (course_id, sort_order)
  WHERE is_published = true;

-- profiles — role-based admin queries
CREATE INDEX IF NOT EXISTS profiles_role_idx
  ON public.profiles (role)
  WHERE role != 'user';


-- ============================================================
-- Migration: 011_adaptive_cache_locks.sql
-- ============================================================
-- Migration 011: Adaptive cache refresh locks
--
-- Adds a `cache_refresh_locks` table that owns the two-threshold TTL and
-- stale-while-revalidate lock for every external-API cache group.
--
-- Each row represents one logical cache group identified by a text key:
--   "odds:<sportKey>"            e.g.  "odds:soccer_epl"
--   "fixtures:<source>"          e.g.  "fixtures:football-data"
--
-- TTL semantics
--   fetched_at ... soft_expires_at (1 h)  ->  always serve from cache
--   soft_expires_at ... hard_expires_at (2 h)
--     last_served_at within 30 min  ->  high traffic  ->  refresh
--     last_served_at older          ->  low traffic   ->  serve stale
--   now > hard_expires_at           ->  must refresh regardless of traffic
--
-- Refresh lock
--   is_refreshing + refreshing_since ensure only ONE concurrent request
--   calls the upstream API per cache group. All others serve the stale row.
--   A lock held for > 2 minutes is considered crashed and auto-cleared.

CREATE TABLE IF NOT EXISTS cache_refresh_locks (
  cache_key         TEXT        PRIMARY KEY,
  fetched_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  soft_expires_at   TIMESTAMPTZ NOT NULL,
  hard_expires_at   TIMESTAMPTZ NOT NULL,
  last_served_at    TIMESTAMPTZ,
  is_refreshing     BOOLEAN     NOT NULL DEFAULT false,
  refreshing_since  TIMESTAMPTZ
);

-- RLS: service-role only (admin client writes; no client-side access needed)
ALTER TABLE cache_refresh_locks ENABLE ROW LEVEL SECURITY;

-- Fast lookup by key (already covered by PRIMARY KEY, but explicit for clarity)
CREATE INDEX IF NOT EXISTS idx_cache_refresh_locks_key
  ON cache_refresh_locks (cache_key);

-- ── fixtures_cache.source constraint fix ────────────────────────────────────
-- Migration 009 only allowed 'api-football' and 'football-data'.
-- The footballdata-io client (primary source) writes 'footballdata-io', which
-- was blocked by that constraint. Replace the constraint using plain ALTER TABLE
-- statements (no DO block needed -- DROP CONSTRAINT IF EXISTS is native SQL).

ALTER TABLE public.fixtures_cache
  DROP CONSTRAINT IF EXISTS fixtures_cache_source_check;

ALTER TABLE public.fixtures_cache
  DROP CONSTRAINT IF EXISTS fixtures_cache_source_check_v2;

ALTER TABLE public.fixtures_cache
  ADD CONSTRAINT fixtures_cache_source_check_v2
  CHECK (source IN ('api-football', 'football-data', 'footballdata-io'));


