-- Migration: 031_historical_matches.sql
-- ============================================================
-- ============================================================
-- PunterStat — Historical Matches + Odds
-- Source: football-data.co.uk (free, no key, 2001/02→present)
-- Covers: EPL, La Liga, Bundesliga, Serie A, Ligue 1
-- Run after 030_option_glossary_seed.sql
-- ============================================================

create table public.historical_matches (
  id           uuid     primary key default gen_random_uuid(),
  source       text     not null default 'football-data-co-uk',
  external_id  text     unique not null,   -- "{league_code}_{date}_{home_slug}_{away_slug}"
  league_code  text     not null,          -- E0 SP1 D1 I1 F1
  league_name  text     not null,
  season       text     not null,          -- "2023/24"
  match_date   date     not null,
  home_team    text     not null,
  away_team    text     not null,

  -- Full-time
  home_goals       smallint,
  away_goals       smallint,
  result           char(1),   -- H D A

  -- Half-time
  ht_home_goals    smallint,
  ht_away_goals    smallint,

  -- Match stats
  home_shots               smallint,
  away_shots               smallint,
  home_shots_on_target     smallint,
  away_shots_on_target     smallint,
  home_corners             smallint,
  away_corners             smallint,
  home_fouls               smallint,
  away_fouls               smallint,
  home_yellow_cards        smallint,
  away_yellow_cards        smallint,
  home_red_cards           smallint,
  away_red_cards           smallint,

  -- xG — populated later via API-Football or Understat
  home_xg   numeric(5,2),
  away_xg   numeric(5,2),

  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create index hm_league_season_idx on public.historical_matches (league_code, season);
create index hm_date_idx          on public.historical_matches (match_date desc);
create index hm_home_team_idx     on public.historical_matches (home_team);
create index hm_away_team_idx     on public.historical_matches (away_team);

-- ------------------------------------------------------------------
-- Odds table — one row per match × bookmaker
-- ------------------------------------------------------------------
create table public.match_odds (
  id         uuid primary key default gen_random_uuid(),
  match_id   uuid not null references public.historical_matches (id) on delete cascade,
  bookmaker  text not null,   -- B365 PS WH VC BW IW ...
  home_odds  numeric(8,3),
  draw_odds  numeric(8,3),
  away_odds  numeric(8,3),
  unique (match_id, bookmaker)
);

create index mo_match_id_idx on public.match_odds (match_id);


-- ============================================================
-- Migration: 032_league_standings_view.sql
-- ============================================================
-- ============================================================
-- PunterStat — League Standings (computed view)
-- Derived live from historical_matches — no separate table needed.
-- Run after 031_historical_matches.sql
-- ============================================================

create or replace view public.league_standings_computed
  with (security_invoker = true)
as
with home_stats as (
  select
    league_code, league_name, season, home_team as team,
    count(*)::int                                                              as played,
    sum(case when result = 'H' then 1 else 0 end)::int                        as won,
    sum(case when result = 'D' then 1 else 0 end)::int                        as drawn,
    sum(case when result = 'A' then 1 else 0 end)::int                        as lost,
    coalesce(sum(home_goals), 0)::int                                         as gf,
    coalesce(sum(away_goals), 0)::int                                         as ga,
    sum(case when result = 'H' then 3 when result = 'D' then 1 else 0 end)::int as pts
  from public.historical_matches
  where result is not null
  group by league_code, league_name, season, home_team
),
away_stats as (
  select
    league_code, league_name, season, away_team as team,
    count(*)::int                                                              as played,
    sum(case when result = 'A' then 1 else 0 end)::int                        as won,
    sum(case when result = 'D' then 1 else 0 end)::int                        as drawn,
    sum(case when result = 'H' then 1 else 0 end)::int                        as lost,
    coalesce(sum(away_goals), 0)::int                                         as gf,
    coalesce(sum(home_goals), 0)::int                                         as ga,
    sum(case when result = 'A' then 3 when result = 'D' then 1 else 0 end)::int as pts
  from public.historical_matches
  where result is not null
  group by league_code, league_name, season, away_team
),
combined as (
  select
    league_code, league_name, season, team,
    sum(played)::int          as played,
    sum(won)::int             as won,
    sum(drawn)::int           as drawn,
    sum(lost)::int            as lost,
    sum(gf)::int              as goals_for,
    sum(ga)::int              as goals_against,
    (sum(gf) - sum(ga))::int  as goal_difference,
    sum(pts)::int             as points
  from (
    select * from home_stats
    union all
    select * from away_stats
  ) t
  group by league_code, league_name, season, team
)
select
  row_number() over (
    partition by league_code, season
    order by points desc, goal_difference desc, goals_for desc, team asc
  )::int as position,
  league_code,
  league_name,
  season,
  team,
  played,
  won,
  drawn,
  lost,
  goals_for,
  goals_against,
  goal_difference,
  points
from combined;


